namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject;

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserInvitationAcceptedByVO
{
    public static function empty(): UserInvitationAcceptedByVO
    {
        return new UserInvitationAcceptedByVO(null);
    }
    public static function from(UserInvitationAcceptedByVO|UserRef|null $value): UserInvitationAcceptedByVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserInvitationAcceptedByVO
    {
        if ($value instanceof UserInvitationAcceptedByVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new UserInvitationAcceptedByVO($value);
        } elseif (is_a($value, UserRef::class)) {
            return new UserInvitationAcceptedByVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['acceptedBy'], [$value], ['UserRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): UserInvitationAcceptedByVO
    {
        if ($value instanceof UserInvitationAcceptedByVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof UserInvitationAcceptedByVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?UserRef $acceptedBy
    ) {
    }
    public function value(): ?UserRef
    {
        return $this->acceptedBy;
    }
    public function equals(?UserInvitationAcceptedByVO $other): bool
    {
        return $this->value()?->uid() == $other?->value()?->uid();
    }
}
